import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    types = {}
    stack = []

    def resolve_type(t):
        if t not in types:
            return 'errtype'
        while isinstance(types[t], str):
            t = types[t]
            if t not in types:
                return 'errtype'
        return t

    def process_typedef(line):
        parts = line.split()
        src = parts[1]
        dst = parts[2]
        src_type = []
        while src.startswith('&'):
            src = src[1:]
            src_type.append('&')
        while src.endswith('*'):
            src = src[:-1]
            src_type.append('*')
        resolved = resolve_type(src)
        if resolved == 'errtype':
            types[dst] = 'errtype'
        else:
            types[dst] = src_type + [resolved]

    def process_typeof(line):
        parts = line.split()
        src = parts[1]

        src_type = []
        while src.startswith('&'):
            src = src[:-1]
            src_type.append('&')
        while src.endswith('*'):
            src =src[:-1]
            src_type.append('*')
        resolved = resolve_type(src)

        if resolved == 'errtype':
            print('errtype')
            return

        final_type = src_type + resolved
        while '&' in final_type:
            idx = final_type.index('&')
            if idx == 0 or final_type[idx-1] != '*':
                print('errtype')
                return
            del final_type[idx-1]
            del final_type[idx-1]
        print('void' + '*' * len(final_type))

    for i in range(1, n+1):
        line = input[i]
        if line.startswith('typedef'):
            process_typedef(line)
        elif line.startswith('typeof'):
            process_typeof(line)

if __name__ == '__main__':
    main()
